  "drain": {
    "kind": "drain",
    "name": "drain",
    "summary": "Cordon a node and evict its pods (PDB-aware); revert re-schedules it (uncordon).",
    "risk": "high",
    "reversible": "snapshot",
    "targets": [
      "Node"
    ],
    "source": "#\n# Cordon the node, then evict every drainable pod (DaemonSet/mirror pods stay) via\n# the PDB-aware Eviction API, retrying pods a budget blocks. The whole-object Node\n# snapshot makes the revert an uncordon; evicted pods are rescheduled by their\n# owners and are not restored.\nnode = args[\"name\"]\nstep(\"snapshot\")\nsnapshot(\"-\", \"Node\", node)\nstep(\"cordon\")\nk8s.patch(\"-\", \"Node\", node, {\"spec\": {\"unschedulable\": True}})\nreport(\"cordoned %s\" % node)\nstep(\"evict pods\")\ndrained = False\nfor _round in range(120):\n    pods = k8s.node_pods(node)\n    if len(pods) == 0:\n        drained = True\n        break\n    report(\"%d pod(s) still on the node\" % len(pods))\n    for p in pods:\n        st = k8s.evict(p[\"namespace\"], p[\"name\"])\n        if st == \"blocked\":\n            report(\"%s/%s blocked by a PodDisruptionBudget — will retry\" % (p[\"namespace\"], p[\"name\"]))\n    sleep(3)\nif not drained:\n    fail(\"node did not drain within the step budget\")\nreport(\"node drained (daemonsets remain)\")\n",
    "full": "# @name drain\n# @summary Cordon a node and evict its pods (PDB-aware); revert re-schedules it (uncordon).\n# @risk high\n# @reversible snapshot\n# @targets Node\n#\n# Cordon the node, then evict every drainable pod (DaemonSet/mirror pods stay) via\n# the PDB-aware Eviction API, retrying pods a budget blocks. The whole-object Node\n# snapshot makes the revert an uncordon; evicted pods are rescheduled by their\n# owners and are not restored.\nnode = args[\"name\"]\nstep(\"snapshot\")\nsnapshot(\"-\", \"Node\", node)\nstep(\"cordon\")\nk8s.patch(\"-\", \"Node\", node, {\"spec\": {\"unschedulable\": True}})\nreport(\"cordoned %s\" % node)\nstep(\"evict pods\")\ndrained = False\nfor _round in range(120):\n    pods = k8s.node_pods(node)\n    if len(pods) == 0:\n        drained = True\n        break\n    report(\"%d pod(s) still on the node\" % len(pods))\n    for p in pods:\n        st = k8s.evict(p[\"namespace\"], p[\"name\"])\n        if st == \"blocked\":\n            report(\"%s/%s blocked by a PodDisruptionBudget — will retry\" % (p[\"namespace\"], p[\"name\"]))\n    sleep(3)\nif not drained:\n    fail(\"node did not drain within the step budget\")\nreport(\"node drained (daemonsets remain)\")\n"
  },
  "drain_preview": {
    "kind": "drain_preview",
    "name": "drain-preview",
    "summary": "Preview which pods a node drain would evict (read-only).",
    "risk": "low",
    "reversible": "readonly",
    "targets": [
      "Node"
    ],
    "source": "#\n# The node is the target (args[\"name\"]). Read-only: list every pod scheduled on the\n# node so an operator can see the blast radius before cordoning or draining.\nnode = args[\"name\"]\nstep(\"preview drain of %s\" % node)\nvictims = [p for p in k8s.pods(\"\") if p.get(\"node\") == node]\nreport(\"%d pod(s) would be evicted\" % len(victims))\nfor p in victims:\n    report(p[\"name\"])\n",
    "full": "# @name drain-preview\n# @summary Preview which pods a node drain would evict (read-only).\n# @risk low\n# @reversible readonly\n# @targets Node\n#\n# The node is the target (args[\"name\"]). Read-only: list every pod scheduled on the\n# node so an operator can see the blast radius before cordoning or draining.\nnode = args[\"name\"]\nstep(\"preview drain of %s\" % node)\nvictims = [p for p in k8s.pods(\"\") if p.get(\"node\") == node]\nreport(\"%d pod(s) would be evicted\" % len(victims))\nfor p in victims:\n    report(p[\"name\"])\n"
  },
  "evict_pod": {
    "kind": "evict_pod",
    "name": "evict-pod",
    "summary": "Gracefully evict one pod via the PDB-aware Eviction API; its owner reschedules it.",
    "risk": "medium",
    "reversible": "none",
    "targets": [
      "Pod"
    ],
    "source": "#\n# The Eviction API respects PodDisruptionBudgets. Not reversible: the replacement\n# is a fresh pod, so there is no prior state to restore. A PDB block fails the action.\nns = args[\"namespace\"]; pod = args[\"name\"]\ngrace = args.get(\"gracePeriodSeconds\", \"\")\nstep(\"evict %s\" % pod)\nstatus = k8s.evict(ns, pod, grace_seconds=int(grace)) if grace != \"\" else k8s.evict(ns, pod)\nif status == \"blocked\":\n    fail(\"eviction blocked by a PodDisruptionBudget\")\nif status == \"notfound\":\n    report(\"pod already gone\")\nelse:\n    report(\"eviction requested — the owning controller will reschedule it\")\n",
    "full": "# @name evict-pod\n# @summary Gracefully evict one pod via the PDB-aware Eviction API; its owner reschedules it.\n# @risk medium\n# @reversible none\n# @targets Pod\n#\n# The Eviction API respects PodDisruptionBudgets. Not reversible: the replacement\n# is a fresh pod, so there is no prior state to restore. A PDB block fails the action.\nns = args[\"namespace\"]; pod = args[\"name\"]\ngrace = args.get(\"gracePeriodSeconds\", \"\")\nstep(\"evict %s\" % pod)\nstatus = k8s.evict(ns, pod, grace_seconds=int(grace)) if grace != \"\" else k8s.evict(ns, pod)\nif status == \"blocked\":\n    fail(\"eviction blocked by a PodDisruptionBudget\")\nif status == \"notfound\":\n    report(\"pod already gone\")\nelse:\n    report(\"eviction requested — the owning controller will reschedule it\")\n"
  },
  "exec_readonly": {
    "kind": "exec_readonly",
    "name": "exec-readonly",
    "summary": "Run one whitelisted read-only command (cat/ls/…) inside a container.",
    "risk": "low",
    "reversible": "readonly",
    "targets": [
      "Pod"
    ],
    "source": "#\n# Read-only: no shell, argv only, output hard-capped. retry catches the short run\n# window of a CrashLooping pod. The command whitelist is enforced by the primitive.\nns = args[\"namespace\"]; pod = args[\"name\"]\ncmd = json.decode(args[\"command\"])\nstep(\"exec %s\" % \" \".join(cmd))\nout = k8s.exec(ns, pod, cmd, container=args.get(\"container\", \"\"), retry=args.get(\"retry\", \"\") == \"true\")\nreport(out)\n",
    "full": "# @name exec-readonly\n# @summary Run one whitelisted read-only command (cat/ls/…) inside a container.\n# @risk low\n# @reversible readonly\n# @targets Pod\n#\n# Read-only: no shell, argv only, output hard-capped. retry catches the short run\n# window of a CrashLooping pod. The command whitelist is enforced by the primitive.\nns = args[\"namespace\"]; pod = args[\"name\"]\ncmd = json.decode(args[\"command\"])\nstep(\"exec %s\" % \" \".join(cmd))\nout = k8s.exec(ns, pod, cmd, container=args.get(\"container\", \"\"), retry=args.get(\"retry\", \"\") == \"true\")\nreport(out)\n"
  },
